#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require

// ACE-Step's 5 Hz LM (ace/lm, MUSIC.md A7): the step between a layer's q/k/v
// projections and its attention, for prefill and decode alike.
//
// Every row of a pass is a token of some sequence: its slot (which KV cache)
// and its position, from the row metadata. One workgroup a (row, head) over
// 32 q heads, then 8 k heads, then 8 v heads, one thread a dim:
//
//   q: RMSNorm over the head (q_norm), NeoX rope at the row's position,
//      times pc.scale (1/sqrt(128)), into the fp16 q the attention reads;
//   k: RMSNorm (k_norm, the 128 after q_norm), rope, into the key cache at
//      (slot, position);
//   v: straight into the value cache at (slot, position).
//
// The cache holds every position ever written, so attention needs nothing
// from the pass but the query: a prefill is the same code as a decode, and
// a prompt can be prefilled in any number of passes.
//
// Fields:
//
//	inOff  q fp32 [rows][32][128]        kOff  k fp32 [rows][8][128]     vOff  v fp32 [rows][8][128]
//	outOff q fp16 [rows][32][128]        wOff  q_norm [128], k_norm [128] (weights arena)
//	aux0   row metadata: (slot, pos) as uint bits, 2 a row
//	aux1   the layer's key cache, aux2 its value cache: fp16 [slot][pos][8][128] (fp16 arena)
//	span   positions a slot holds        bOff  rope cos [pos][64], then sin (weights arena)
//	kStride  the rope table's positions  eps, scale, tokens (rows)
//
// PaddleOCR-VL's ERNIE-4.5-0.3B (ocr/lm.go) is the same step with three
// build switches: NQ=16 NKV=2, QK_NORM=0 (it has none), and MROPE=1, its
// 3-D rope. Under MROPE a row's rope positions are three numbers, (t, h, w)
// as uint bits at pc.dim + row*3, apart from its cache position (text after
// an image resumes at p + max(mh, mw), not at its cache index), and each of
// the 64 frequency pairs reads one of them in *chunked* sections: pairs
// 0-15 t, 16-39 h, 40-63 w (HF's recomposition_frequencies, [16, 24, 24]).
// The table is still one [pos][64] over one inv_freq: only the position a
// pair reads changes.

#include "dit_common.glsl"

layout(binding = 2) buffer HAct { float16_t hact[]; };

#define HD 128u
#ifndef NQ
#define NQ 32u
#endif
#ifndef NKV
#define NKV 8u
#endif
#ifndef QK_NORM
#define QK_NORM 1
#endif
#ifndef MROPE
#define MROPE 0
#endif

layout(local_size_x = 128) in;

shared float red[128];

void main() {
    uint r = gl_WorkGroupID.x;
    uint y = gl_WorkGroupID.y;
    uint t = gl_LocalInvocationID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint slot = floatBitsToUint(act[pc.aux0 + r * 2u]);
    uint pos = floatBitsToUint(act[pc.aux0 + r * 2u + 1u]);
    uint cell = ((slot * pc.span + pos) * NKV) * HD;

    if (y >= NQ + NKV) {
        uint h = y - NQ - NKV;
        hact[pc.aux2 + cell + h * HD + t] = float16_t(act[pc.vOff + (r * NKV + h) * HD + t]);
        return;
    }
    bool isQ = y < NQ;
    uint h = isQ ? y : y - NQ;
    uint src = isQ ? pc.inOff + (r * NQ + h) * HD : pc.kOff + (r * NKV + h) * HD;
    float x = act[src + t];

#if QK_NORM
    red[t] = x * x;
    barrier();
    for (uint s = 64u; s > 0u; s >>= 1) {
        if (t < s) {
            red[t] += red[t + s];
        }
        barrier();
    }
    float inv = inversesqrt(red[0] / float(HD) + uintBitsToFloat(pc.eps));
    float xn = x * inv * wbuf[pc.wOff + (isQ ? 0u : HD) + t];
    barrier(); // every thread has read red[0] before red is reused
#else
    float xn = x;
#endif

    // NeoX: dim i pairs with i ± 64 at the frequency of i mod 64.
    red[t] = xn;
    barrier();
    uint i = t % 64u;
#if MROPE
    uint axis = i < 16u ? 0u : (i < 40u ? 1u : 2u);
    uint rp = floatBitsToUint(act[pc.dim + r * 3u + axis]);
#else
    uint rp = pos;
#endif
    float c = wbuf[pc.bOff + rp * 64u + i];
    float s = wbuf[pc.bOff + pc.kStride * 64u + rp * 64u + i];
    float y2 = t < 64u ? xn * c - red[t + 64u] * s : xn * c + red[t - 64u] * s;

    if (isQ) {
        hact[pc.outOff + (r * NQ + h) * HD + t] = float16_t(y2 * uintBitsToFloat(pc.scale));
    } else {
        hact[pc.aux1 + cell + h * HD + t] = float16_t(y2);
    }
}
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_KHR_shader_subgroup_arithmetic : require

// ACE-Step's 5 Hz LM (ace/lm, MUSIC.md A7): causal GQA attention of a pass's
// rows over the KV cache, split over the keys.
//
// A row at position p of slot s sees that slot's keys 0..p, which ace_lm_prep
// has already written, this pass's included. So a prefill pass and a decode
// step are the same dispatch; they differ in how many rows there are and how
// long a chunk of keys is.
//
// Default build: one 64-lane workgroup a (row, q head + 32 x chunk of
// pc.aux1 keys). Keys are taken 64 at a time: lane j scores key j against the head's
// q (fp16 cache, fp32 sums, q pre-scaled by 1/sqrt(128)), the block's max
// and sum are subgroup reductions, and then each lane accumulates two dims
// of p·V over the block. The chunk's (max, sum, o[128]) go to the partials.
//
// COMBINE: one workgroup a (row, q head) merges the chunks that hold keys
// and writes o / sum into o_proj's fp16 A operand.
//
// Fields:
//
//	inOff  q fp16 [rows][32][128] (COMBINE: the partials)
//	outOff the partials, fp32 [rows][32][aux2][130] (COMBINE: the fp16 A operand, row stride dim)
//	kOff, vOff  the layer's caches, fp16 [slot][pos][8][128]
//	aux0   row metadata (slot, pos)      span  positions a slot holds
//	aux1   keys a chunk                  aux2  chunks a (row, head)
//	tokens rows                          dim   COMBINE: the A operand's row stride

#include "dit_common.glsl"

layout(binding = 2) buffer HAct { float16_t hact[]; };

#define HD 128u
#ifndef NQ
#define NQ 32u // ocr/lm.go builds 16 and 2
#endif
#ifndef NKV
#define NKV 8u
#endif
#define PSTRIDE 130u

layout(local_size_x = 64) in;

#ifndef COMBINE

shared float qs[HD];
shared float ps[64];

void main() {
    uint r = gl_WorkGroupID.x;
    uint h = gl_WorkGroupID.y % NQ;
    uint c = gl_WorkGroupID.y / NQ; // vk.MultiDispatch has no z
    uint lane = gl_LocalInvocationID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint slot = floatBitsToUint(act[pc.aux0 + r * 2u]);
    uint pos = floatBitsToUint(act[pc.aux0 + r * 2u + 1u]);
    uint n = pos + 1u;
    uint k0 = c * pc.aux1;
    if (k0 >= n) {
        return; // COMBINE never reads a chunk past the row's keys
    }
    uint k1 = min(n, k0 + pc.aux1);
    uint g = h / (NQ / NKV);

    uint q = pc.inOff + (r * NQ + h) * HD;
    qs[lane] = float(hact[q + lane]);
    qs[lane + 64u] = float(hact[q + lane + 64u]);
    barrier();

    uint base = (slot * pc.span * NKV + g) * HD; // + key * NKV * HD
    float m = -1.0 / 0.0;
    float l = 0.0;
    float o0 = 0.0, o1 = 0.0;
    for (uint b = k0; b < k1; b += 64u) {
        uint kj = b + lane;
        float s = -1.0 / 0.0;
        if (kj < k1) {
            uint kb = pc.kOff + base + kj * NKV * HD;
            s = 0.0;
            for (uint d = 0u; d < HD; d++) {
                s += qs[d] * float(hact[kb + d]);
            }
        }
        float mn = max(m, subgroupMax(s));
        float corr = exp(m - mn);
        float p = kj < k1 ? exp(s - mn) : 0.0;
        l = l * corr + subgroupAdd(p);
        ps[lane] = p;
        barrier();
        o0 *= corr;
        o1 *= corr;
        uint cnt = min(64u, k1 - b);
        uint vb = pc.vOff + base + b * NKV * HD + lane * 2u;
        for (uint j = 0u; j < cnt; j++) {
            float pj = ps[j];
            o0 += pj * float(hact[vb + j * NKV * HD]);
            o1 += pj * float(hact[vb + j * NKV * HD + 1u]);
        }
        barrier();
        m = mn;
    }
    uint out_ = pc.outOff + ((r * NQ + h) * pc.aux2 + c) * PSTRIDE;
    if (lane == 0u) {
        act[out_] = m;
        act[out_ + 1u] = l;
    }
    act[out_ + 2u + lane * 2u] = o0;
    act[out_ + 3u + lane * 2u] = o1;
}

#else

void main() {
    uint r = gl_WorkGroupID.x;
    uint h = gl_WorkGroupID.y;
    uint lane = gl_LocalInvocationID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint pos = floatBitsToUint(act[pc.aux0 + r * 2u + 1u]);
    uint chunks = (pos + pc.aux1) / pc.aux1; // ceil((pos + 1) / aux1)
    uint base = pc.inOff + (r * NQ + h) * pc.aux2 * PSTRIDE;
    float mx = -1.0 / 0.0;
    for (uint c = 0u; c < chunks; c++) {
        mx = max(mx, act[base + c * PSTRIDE]);
    }
    float l = 0.0, o0 = 0.0, o1 = 0.0;
    for (uint c = 0u; c < chunks; c++) {
        uint p = base + c * PSTRIDE;
        float w = exp(act[p] - mx);
        l += act[p + 1u] * w;
        o0 += act[p + 2u + lane * 2u] * w;
        o1 += act[p + 3u + lane * 2u] * w;
    }
    uint dst = pc.outOff + r * pc.dim + h * HD + lane * 2u;
    hact[dst] = float16_t(o0 / l);
    hact[dst + 1u] = float16_t(o1 / l);
}

#endif

