func (g *LM) Reserve(slot, n int) error {
	if slot < 0 || slot >= g.o.Slots || n > g.o.MaxLen {
		return fmt.Errorf("ocr: %d positions in slot %d; the cache is %d x %d", n, slot, g.o.Slots, g.o.MaxLen)
