	j := &job{req: req, im: im, p: p, maxTok: maxTok, slot: -1,
		res:    &Result{PromptTokens: len(p.IDs), GridH: im.GridH, GridW: im.GridW, Process: time.Since(t0)},
		tokens: make(chan int32, maxTok+1), done: make(chan error, 1)}
