	if first != nil {
		if ctx.Err() != nil && context.Cause(ctx) == nil {
			return nil, first
		}
		return nil, first
	}
	return out, nil
}

// wait delivers a job's tokens to OnToken and returns its end.
func (e *Engine) wait(j *job, cancel func()) error {
	var cbErr error
