// Input is one image of ForwardMany: its patches and grid, and optionally
// its geometry, already computed (Model.Geometry's or the tower's own when
// nil), so a caller can build it off the device's critical path.
type Input struct {
	Pixels       *qwen.Mat
	GridH, GridW int
	Pos          *qwen.Mat
	Rope         *Rope
}

// Geometry is the position grid and rope tables Forward would use for a
// grid.
func (g *GPU) Geometry(gridH, gridW int) (*qwen.Mat, *Rope, error) {
	if g.cpu.Geometry != nil {
		return g.cpu.Geometry(gridH, gridW)
	}
	pos, err := g.cpu.positionEmbedding(gridH, gridW)
	if err != nil {
		return nil, nil, err
	}
	return pos, NewRope(&g.cfg, gridH, gridW), nil
}

// ForwardMany runs several images through the tower in one graph (OCR.md
// O11): their rows are concatenated, so every GEMM, norm and the merger run
// once over all of them, and only attention runs an image at a time. A small
// image's tower is a few hundred dispatches that the device spends mostly
// waiting between, so eight small crops cost about what one does. Each
// image's rows are a multiple of the merge group, so the merger's four-row
// groups never straddle two images. The budget is the sum of their patches.
func (g *GPU) ForwardMany(ctx context.Context, ins []Input) ([]*Output, error) {
	merge := g.cfg.SpatialMergeSize * g.cfg.SpatialMergeSize
	if len(ins) == 0 {
		return nil, fmt.Errorf("vision: no images")
	}
	if len(ins) > 1 && (g.scalar || g.Tap != nil) {
		return nil, fmt.Errorf("vision: several images at once need the WMMA attention and no taps")
	}
	starts := make([]int, len(ins)+1)
	for i, in := range ins {
		rows := in.GridH * in.GridW
		if in.GridH <= 0 || in.GridW <= 0 || rows%merge != 0 {
			return nil, fmt.Errorf("vision: a %dx%d grid does not group into %ds", in.GridH, in.GridW, merge)
		}
		if in.Pixels.Rows != rows || in.Pixels.Cols != g.cfg.PatchElems() {
			return nil, fmt.Errorf("vision: pixels are %s, want [%d %d]", in.Pixels, rows, g.cfg.PatchElems())
		}
		starts[i+1] = starts[i] + rows
	}
	rows := starts[len(ins)]
	if rows > g.maxRows {
		if len(ins) == 1 {
			return nil, fmt.Errorf("vision: a %dx%d grid is %d patches, staged for %d",
				ins[0].GridH, ins[0].GridW, rows, g.maxRows)
		}
		return nil, fmt.Errorf("vision: %d images of %d patches, staged for %d", len(ins), rows, g.maxRows)
	}
	g.gridH, g.gridW, g.rows, g.merged = ins[0].GridH, ins[0].GridW, rows, rows/merge
	for i, in := range ins {
		pos, rope := in.Pos, in.Rope
		if pos == nil || rope == nil {
			var err error
			if pos, rope, err = g.Geometry(in.GridH, in.GridW); err != nil {
				return nil, err
			}
		}
		n, at := starts[i+1]-starts[i], starts[i]
		px := in.Pixels.Data
		if pe := g.cfg.PatchElems(); g.patchK != pe {
			// Zero K columns, which the narrowing carries into the A operand.
			px = padWeight(px, n, pe, n, g.patchK)
		}
		g.abuf.WriteFloat32At(int(g.aPix)+at*g.patchK, px)
		g.abuf.WriteFloat32At(int(g.aPos)+at*g.dim, pos.Data)
		g.abuf.WriteFloat32At(int(g.aCos)+at*g.headDim, rope.Cos.Data)
		g.abuf.WriteFloat32At(int(g.aSin)+at*g.headDim, rope.Sin.Data)
	}
