		g.abuf.WriteFloat32At(int(g.aPos)+at*g.dim, pos.Data)
		g.abuf.WriteFloat32At(int(g.aCos)+at*g.headDim, rope.Cos.Data)
		g.abuf.WriteFloat32At(int(g.aSin)+at*g.headDim, rope.Sin.Data)
