rep('''// blockOrder lists''','''// Stage is an image's host side of the tower, ready for ForwardMany: its
// patches, position grid and rope in block order. It touches no device
// state, so it can run on any goroutine.
func (gt *GPUTower) Stage(im *Image) (vision.Input, error) {
	gh, gw := im.GridH, im.GridW
	if gh%MergeSize != 0 || gw%MergeSize != 0 || len(im.Patches) != gh*gw*PatchElems {
		return vision.Input{}, fmt.Errorf("ocr: %d values for a %dx%d patch grid", len(im.Patches), gw, gh)
	}
	order := blockOrder(gh, gw)
	pos, rope := gt.t.positionEmbedding(gh, gw), rasterRope(gh, gw)
	return vision.Input{
		Pixels: gather(&qwen.Mat{Rows: gh * gw, Cols: PatchElems, Data: im.Patches}, order),
		GridH:  gh, GridW: gw,
		Pos:  gather(pos, order),
		Rope: &vision.Rope{Cos: gather(rope.Cos, order), Sin: gather(rope.Sin, order)},
	}, nil
}

// ForwardMany runs staged images together (OCR.md O11), at most
// MaxPatches() patches in all, and returns each one's image-token rows.
func (gt *GPUTower) ForwardMany(ctx context.Context, ins []vision.Input) ([]*qwen.Mat, error) {
	gt.g.Tap = nil
	outs, err := gt.g.ForwardMany(ctx, ins)
	if err != nil {
		return nil, err
	}
	m := make([]*qwen.Mat, len(outs))
	for i, o := range outs {
		m[i] = o.Merged
	}
	return m, nil
}

// MaxPatches is the staged budget: one image's, or a ForwardMany's sum.
func (gt *GPUTower) MaxPatches() int { return gt.g.MaxRows() }

// blockOrder lists''')
open(p,'w').write(s)
