func (e *Engine) admit() {
	var fresh []*job
	promised := len(e.active)
	for len(e.waiting) > 0 && len(e.slots) > 0 {
		j := e.waiting[0]
		need := (j.target() + PageSize - 1) / PageSize
		if len(e.active) > 0 && e.lm.FreePages() < promised+need {
