// runTowers runs jobs' towers in one pass and splices each one's image rows
// into its prompt.
func (e *Engine) runTowers(js []*job) error {
	t0 := time.Now()
	ctx := context.Background()
	if len(js) == 1 {
		ctx = js[0].ctx
	}
	ins := make([]vision.Input, len(js))
	for i, j := range js {
		ins[i] = j.stage
	}
	err := e.do(func() error {
		vis, err := e.tower.ForwardMany(ctx, ins)
		if err != nil {
			return err
		}
		for i, j := range js {
			if vis[i].Rows != j.p.ImageLen {
				return fmt.Errorf("ocr: the tower gave %d rows for %d image tokens", vis[i].Rows, j.p.ImageLen)
