	})
	if err != nil {
		return err
	}
	now := time.Now()
	for _, j := range js {
		j.towered = now
		j.res.Tower = now.Sub(t0)
		j.stage = vision.Input{}
	}
	e.count(func(s *Stats) { s.Towers++; s.Images += len(js); s.Tower += now.Sub(t0) })
	return nil
